// Piksel Ofis etkinlik şeritleri: masadaki işin küçük piksel propları (özgün çizimler) ve gövde/sahne
// @keyframes'leri. Her şerit yatay bir PNG ya da SVG rect dizisidir: n kare, fw x fh prop pikseli,
// pa = prop_anker. ao = anker_ofseti (karakter türü -> [x, y], prop pikseli, y aşağı +). ACT_CSS gövde/kare/
// sahne @keyframes'leri; px değerleri calc(var(--u)*Npx) (u = propUnit).
import type { CharKind, CharState } from './char-data'

export type ActClass = 'gorev' | 'olay' | 'ambiyans'
export type ActAnchor = 'yan' | 'el' | 'kafa' | 'kafa_govde' | 'goz' | 'ust_yan'
/** bir serit: n kare, kare fw x fh (PNG genisligi / kare), pa = prop_anker */
export type ActStrip = { n: number; fw: number; fh: number; pa: readonly [number, number]; b64?: string; svg?: string }
export type ActEntry = {
  id: string
  cls: ActClass; prio: number; prob: number
  fps: number
  /** sure === 'tek' */
  once: boolean
  /** giris_kare: ilk intro kare bir kez, dongu intro. kareden */
  intro: number
  pingpong: boolean
  layer: 'on' | 'arka'
  /** taban_durum */
  base: CharState
  anchor: ActAnchor
  ao: Readonly<Record<CharKind, readonly [number, number]>>
  /** ACT_STRIPS anahtari; headset aile seritleri */
  strip: Readonly<Partial<Record<CharKind, string>>> & { readonly def: string }
  /** sahne_translate x, y, sure_ms (paper-plane) */
  move?: readonly [number, number, number]
  /** govde CSS (ACT_CSS icinde, ad acb-<id>) */
  body?: { name: string; ms: number; ease: string; count: number | 'infinite' }
  /** kafa_degistir: şapka başın üstüne oturur */
  head?: true
  /** varyant_of | ek_katman_of | opsiyonel_katman_of */
  of?: string
  role: 'ana' | 'varyant' | 'ek_katman' | 'opsiyonel_katman'
  /** opsiyonel_katmanlar */
  layers?: readonly string[]
}

